import{_ as p,o as r,c as o,a2 as n}from"./chunks/framework.ost63GJL.js";const c=JSON.parse('{"title":"中华人民共和国注册会计师法（2026年修正）","description":"","frontmatter":{"title":"中华人民共和国注册会计师法（2026年修正）"},"headers":[],"relativePath":"auditing/cpal/2026.md","filePath":"auditing/cpal/2026.md","lastUpdated":null}'),s={name:"auditing/cpal/2026.md"};function g(a,t,e,l,i,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="中华人民共和国注册会计师法-2026年修正" tabindex="-1">中华人民共和国注册会计师法（2026年修正） <a class="header-anchor" href="#中华人民共和国注册会计师法-2026年修正" aria-label="Permalink to &quot;中华人民共和国注册会计师法（2026年修正）&quot;">​</a></h1><h2 id="发文信息" tabindex="-1">发文信息 <a class="header-anchor" href="#发文信息" aria-label="Permalink to &quot;发文信息&quot;">​</a></h2><ul><li><strong>发文机关</strong>：全国人民代表大会常务委员会</li><li><strong>发布日期</strong>：2026-06-26</li><li><strong>生效日期</strong>：2027-01-01</li><li><strong>时效性</strong>：尚未生效</li><li><strong>文号</strong>：中华人民共和国主席令第七十八号</li></ul><blockquote><p>1993年10月31日第八届全国人民代表大会常务委员会第四次会议通过，根据2014年8月31日第十二届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国保险法〉等五部法律的决定》第一次修正，根据2026年6月26日第十四届全国人民代表大会常务委员会第二十三次会议《关于修改〈中华人民共和国注册会计师法〉的决定》第二次修正。</p></blockquote><h2 id="第一章-总则" tabindex="-1">第一章 总则 <a class="header-anchor" href="#第一章-总则" aria-label="Permalink to &quot;第一章 总则&quot;">​</a></h2><p><strong>第一条</strong>　为了发挥注册会计师在社会经济活动中的鉴证和服务作用，加强对注册会计师的管理，维护社会公共利益和投资者的合法权益，促进社会主义市场经济的健康发展，制定本法。</p><p><strong>第二条</strong>　注册会计师行业坚持中国共产党的领导，贯彻落实党和国家路线方针政策、决策部署，为国民经济和社会发展服务。</p><p><strong>第三条</strong>　注册会计师是依法取得注册会计师证书并接受委托从事审计和会计咨询、会计服务业务的执业人员。</p><p><strong>第四条</strong>　会计师事务所是依法设立并承办注册会计师业务的机构。注册会计师执行业务，应当加入会计师事务所。</p><p><strong>第五条</strong>　注册会计师协会是由注册会计师组成的社会团体。中国注册会计师协会是注册会计师的全国组织，省、自治区、直辖市注册会计师协会是注册会计师的地方组织。</p><p><strong>第六条</strong>　国务院财政部门和省、自治区、直辖市人民政府财政部门，依法对注册会计师、会计师事务所和注册会计师协会进行监督、指导。</p><p><strong>第七条</strong>　国家支持注册会计师行业加强诚信建设，提高审计质量，拓展服务网络，提升规范化、专业化水平，促进注册会计师行业健康发展。</p><p><strong>第八条</strong>　注册会计师和会计师事务所执行业务，必须遵守法律、行政法规，遵循执业准则，恪守职业道德，坚持诚信、客观、独立、公正。注册会计师和会计师事务所依法执行业务，受法律保护；其合法权益不受侵害。</p><h2 id="第二章-考试和注册" tabindex="-1">第二章 考试和注册 <a class="header-anchor" href="#第二章-考试和注册" aria-label="Permalink to &quot;第二章 考试和注册&quot;">​</a></h2><p><strong>第九条</strong>　国家实行注册会计师全国统一考试制度。注册会计师全国统一考试办法，由国务院财政部门制定，由中国注册会计师协会组织实施。</p><p><strong>第十条</strong>　具有高等专科以上学校毕业的学历、或者具有会计或者相关专业中级以上技术职称的中国公民，可以申请参加注册会计师全国统一考试；具有会计或者相关专业高级技术职称的人员，可以免予部分科目的考试。</p><p><strong>第十一条</strong>　参加注册会计师全国统一考试成绩合格，并从事审计业务工作二年以上的，可以向省、自治区、直辖市注册会计师协会申请注册。</p><p><strong>第十二条</strong>　有下列情形之一的，受理申请的注册会计师协会不予注册：</p><p>（一）不具有完全民事行为能力；</p><p>（二）因受刑事处罚，自刑罚执行完毕之日起至申请注册之日止不满五年；</p><p>（三）因在财务、会计、审计、企业管理或者其他经济管理工作中犯有严重错误受行政处罚、撤职以上处分，自处罚、处分决定之日起至申请注册之日止不满二年；</p><p>（四）受吊销注册会计师证书的处罚，自处罚决定之日起至申请注册之日止不满五年；</p><p>（五）被处以终身禁止从事注册会计师业务处罚；</p><p>（六）国务院财政部门规章规定的其他不予注册的情形。</p><p><strong>第十三条</strong>　注册会计师协会应当将准予注册的人员名单报国务院财政部门备案。</p><p><strong>第十四条</strong>　准予注册的申请人，由注册会计师协会发给国务院财政部门统一制定的注册会计师证书。</p><p><strong>第十五条</strong>　已取得注册会计师证书的人员，注册后有下列情形之一的，由准予注册的注册会计师协会注销或者撤销注册，收回注册会计师证书：</p><p>（一）完全丧失民事行为能力；</p><p>（二）受刑事处罚；</p><p>（三）因在财务、会计、审计、企业管理或者其他经济管理工作中犯有严重错误受行政处罚、撤职以上处分；</p><p>（四）自行停止执行注册会计师业务满一年；</p><p>（五）依法应当注销或者撤销注册的其他情形。</p><h2 id="第三章-业务范围和规则" tabindex="-1">第三章 业务范围和规则 <a class="header-anchor" href="#第三章-业务范围和规则" aria-label="Permalink to &quot;第三章 业务范围和规则&quot;">​</a></h2><p><strong>第十六条</strong>　注册会计师承办下列审计业务：</p><p>（一）审查企业会计报表，出具审计报告；</p><p>（二）验证企业资本，出具验资报告；</p><p>（三）办理企业合并、分立、清算事宜中的审计业务，出具有关的报告；</p><p>（四）法律、行政法规规定的其他审计业务。</p><p>注册会计师依法执行审计业务出具的报告，具有证明效力。</p><p><strong>第十七条</strong>　注册会计师可以承办会计咨询、会计服务业务。</p><p><strong>第十八条</strong>　注册会计师承办业务，由其所在的会计师事务所统一受理并与委托人签订委托合同。</p><p><strong>第十九条</strong>　注册会计师执行业务，可以根据需要查阅被审计单位以及相关单位和个人的有关会计资料和文件，查看被审计单位的业务现场和设施，要求委托人或者被审计单位提供其他必要的协助。</p><p><strong>第二十条</strong>　注册会计师与委托人或者被审计单位有利害关系的，应当回避；委托人或者被审计单位有权要求其回避。</p><p><strong>第二十一条</strong>　注册会计师对在执行业务中知悉的国家秘密、工作秘密、商业秘密、个人隐私、个人信息，负有保密义务，不得泄露或者非法向他人提供。</p><p><strong>第二十二条</strong>　注册会计师执行审计业务，遇有下列情形之一的，应当拒绝出具有关报告，或者出具非无保留意见的报告：</p><p>（一）委托人或者被审计单位示意其作不实或者不当证明；</p><p>（二）被审计单位以及相关单位和个人故意不提供有关会计资料和文件；</p><p>（三）因委托人或者被审计单位有其他不合理要求，致使注册会计师出具的报告不能对财务会计的重要事项作出正确表述。</p><p><strong>第二十三条</strong>　注册会计师执行审计业务，必须以国家统一的会计制度为依据，按照执业准则、规则确定的工作程序出具报告，不得出具虚假报告。</p><p><strong>第二十四条</strong>　注册会计师不得有下列行为：</p><p>（一）在执行审计业务期间，在法律、行政法规规定不得买卖被审计单位的证券或者不得购买被审计单位或者个人的其他财产的期限内，买卖被审计单位的证券或者购买被审计单位或者个人所拥有的其他财产；</p><p>（二）索取、收受委托合同约定以外的酬金或者其他财物，或者利用执行业务之便，谋取其他不正当的利益；</p><p>（三）接受委托催收债款；</p><p>（四）冒用他人名义执行业务，或者允许他人以本人名义执行业务；</p><p>（五）同时在两个或者两个以上的会计师事务所执行业务；</p><p>（六）对其能力进行广告宣传以招揽业务或者采用强迫、欺诈、贿赂等不正当方式招揽业务；</p><p>（七）违反法律、行政法规的其他行为。</p><h2 id="第四章-会计师事务所" tabindex="-1">第四章 会计师事务所 <a class="header-anchor" href="#第四章-会计师事务所" aria-label="Permalink to &quot;第四章 会计师事务所&quot;">​</a></h2><p><strong>第二十五条</strong>　会计师事务所可以由注册会计师合伙设立。合伙设立的会计师事务所应当采用普通合伙或者特殊的普通合伙形式。</p><p><strong>第二十六条</strong>　会计师事务所符合下列条件的，可以是负有限责任的法人：</p><p>（一）不少于三十万元的注册资本；</p><p>（二）有一定数量的专职从业人员，其中至少有五名注册会计师；</p><p>（三）国务院财政部门规定的其他条件。</p><p><strong>第二十七条</strong>　设立会计师事务所，由省、自治区、直辖市人民政府财政部门批准。</p><p><strong>第二十八条</strong>　审批机关应当自收到申请文件之日起十五日内决定批准或者不批准。设立会计师事务所应当自批准之日起六十日内，向承担经营主体登记工作的部门办理登记。</p><p><strong>第二十九条</strong>　会计师事务所设立分支机构，须经分支机构所在地的省、自治区、直辖市人民政府财政部门批准。</p><p><strong>第三十条</strong>　会计师事务所依法纳税。会计师事务所按照国务院财政部门的规定建立职业风险基金，办理职业保险。</p><p><strong>第三十一条</strong>　会计师事务所受理业务，不受行政区域、行业的限制；但是，法律、行政法规另有规定的除外。</p><p><strong>第三十二条</strong>　国务院财政部门会同国务院有关部门依照有关法律规定，对会计师事务所从事上市公司审计等金融活动审计服务实施准入管理。</p><p><strong>第三十三条</strong>　委托人委托会计师事务所办理业务，任何单位和个人不得干预。</p><p><strong>第三十四条</strong>　本法第二十条至第二十三条的规定，适用于会计师事务所。</p><p><strong>第三十五条</strong>　会计师事务所不得有本法第二十四条第（一）项至第（四）项、第（六）项、第（七）项所列的行为。</p><h2 id="第五章-注册会计师协会" tabindex="-1">第五章 注册会计师协会 <a class="header-anchor" href="#第五章-注册会计师协会" aria-label="Permalink to &quot;第五章 注册会计师协会&quot;">​</a></h2><p><strong>第三十六条</strong>　注册会计师应当加入注册会计师协会。</p><p><strong>第三十七条</strong>　中国注册会计师协会的章程由全国会员代表大会制定，并报国务院财政部门备案；省、自治区、直辖市注册会计师协会的章程由省、自治区、直辖市会员代表大会制定，并报省、自治区、直辖市人民政府财政部门备案。</p><p><strong>第三十八条</strong>　中国注册会计师协会依法拟订注册会计师执业准则、规则，报国务院财政部门批准后施行。</p><p><strong>第三十九条</strong>　注册会计师协会应当加强注册会计师行业有关发展规划和人才队伍建设工作，强化行业自律监督，为提升行业服务质量，拓展业务领域和创新技术应用提供支持。</p><p><strong>第四十条</strong>　注册会计师协会应当对注册会计师的任职资格和执业情况进行年度检查。</p><p><strong>第四十一条</strong>　注册会计师协会依法取得社会团体法人资格。</p><h2 id="第六章-监督管理" tabindex="-1">第六章 监督管理 <a class="header-anchor" href="#第六章-监督管理" aria-label="Permalink to &quot;第六章 监督管理&quot;">​</a></h2><p><strong>第四十二条</strong>　国务院财政部门和省、自治区、直辖市人民政府财政部门依法对会计师事务所、注册会计师的执业情况进行监督检查。</p><p><strong>第四十三条</strong>　国务院财政部门或者省、自治区、直辖市人民政府财政部门对会计师事务所、注册会计师依法实施监督检查时，会计师事务所、注册会计师应当如实提供有关审计资料和文件，不得拒绝、阻碍或者隐瞒。</p><p><strong>第四十四条</strong>　国务院财政部门或者省、自治区、直辖市人民政府财政部门在监督检查中发现会计师事务所、注册会计师有违规行为的，可以采取监管谈话、出具警示函、责令限期整改等措施。</p><p><strong>第四十五条</strong>　会计师事务所应当加强对审计工作底稿和审计档案的管理，保证其真实、完整。注册会计师执行审计业务形成的审计工作底稿和审计档案，应当存放在中国境内。除国家另有规定外，任何单位或者个人不得擅自携带、传递审计工作底稿或者审计档案出境。</p><p><strong>第四十六条</strong>　国务院财政部门和省、自治区、直辖市人民政府财政部门应当加强信息化建设，提升注册会计师行业的监管效率和水平。</p><h2 id="第七章-法律责任" tabindex="-1">第七章 法律责任 <a class="header-anchor" href="#第七章-法律责任" aria-label="Permalink to &quot;第七章 法律责任&quot;">​</a></h2><p><strong>第四十七条</strong>　会计师事务所违反本法第二十二条、第二十三条规定的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，违法所得五十万元以上的，可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足五十万元的，可以并处五百万元以下的罚款；情节严重的，暂停其部分或者全部经营业务一个月至十二个月或者吊销其执业许可。对直接负责的主管人员和其他直接责任人员，责令限期改正，给予警告、通报批评，没收违法所得，可以并处二百万元以下的罚款。</p><p>注册会计师违反本法第二十二条、第二十三条规定的，依照本条第一款关于直接负责的主管人员和其他直接责任人员的规定处理，情节严重的，暂停其执行业务一个月至十二个月或者吊销其注册会计师证书。</p><p>注册会计师违反本法第二十二条、第二十三条的规定，构成故意犯罪的，终身不得从事注册会计师业务。</p><p><strong>第四十八条</strong>　会计师事务所违反本法第三十五条规定的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，违法所得十万元以上的，可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足十万元的，可以并处一百万元以下的罚款；情节严重的，暂停其部分或者全部经营业务一个月至十二个月或者吊销其执业许可。</p><p><strong>第四十九条</strong>　委托人或者被审计单位以及其他单位或者个人串通、唆使会计师事务所或者注册会计师违反本法第二十二条、第二十三条规定出具虚假报告的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门，责令其限期改正，给予警告、通报批评，没收违法所得，可以并处五百万元以下的罚款。</p><p><strong>第五十条</strong>　对未经批准承办本法第十六条规定的注册会计师业务的单位或者个人，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令其停止违法活动，没收违法所得，违法所得五十万元以上的，可以并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足五十万元的，可以并处五百万元以下的罚款。</p><p><strong>第五十一条</strong>　被审计单位以及相关单位和个人向注册会计师提供虚假的会计资料或者文件的，依照有关法律、行政法规的规定处罚。</p><p><strong>第五十二条</strong>　会计师事务所、注册会计师违反本法第四十三条规定的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，可以并处二十万元以下的罚款；情节严重的，处二十万元以上一百万元以下的罚款。</p><p><strong>第五十三条</strong>　任何单位或者个人违反本法第四十五条规定，擅自携带、传递审计工作底稿或者审计档案出境的，由国务院财政部门或者省、自治区、直辖市人民政府财政部门责令限期改正，给予警告、通报批评，没收违法所得，对单位可以并处二百万元以下的罚款，对直接负责的主管人员和其他直接责任人员可以并处五十万元以下的罚款。</p><p><strong>第五十四条</strong>　财政部门、注册会计师协会工作人员在注册会计师行业监督管理工作中滥用职权、玩忽职守、徇私舞弊或者泄露国家秘密、工作秘密、商业秘密、个人隐私、个人信息的，依法给予处分。</p><p><strong>第五十五条</strong>　当事人对行政处罚决定不服的，可以依法申请行政复议或者向人民法院提起行政诉讼。</p><p><strong>第五十六条</strong>　会计师事务所违反本法规定，给委托人、被审计单位以及其他利害关系人造成损失的，应当依法承担赔偿责任。</p><p><strong>第五十七条</strong>　违反本法规定，构成犯罪的，依法追究刑事责任。</p><h2 id="第八章-附则" tabindex="-1">第八章 附则 <a class="header-anchor" href="#第八章-附则" aria-label="Permalink to &quot;第八章 附则&quot;">​</a></h2><p><strong>第五十八条</strong>　外国人申请参加中国注册会计师全国统一考试和注册，按照互惠原则办理。外国会计师事务所需要在中国境内临时办理有关业务的，须经有关的省、自治区、直辖市人民政府财政部门批准。</p><p><strong>第五十九条</strong>　国务院可以根据本法制定实施条例。</p><p><strong>第六十条</strong>　本法自1994年1月1日起施行。1986年7月3日国务院发布的《中华人民共和国注册会计师条例》同时废止。</p>',103)])])}const u=p(s,[["render",g]]);export{c as __pageData,u as default};
